/* Petshop Newsletter v1.0 — forma be perkrovimo. */
(function () {
	'use strict';
	function init(root) {
		var email = root.querySelector('.psnl-email');
		var btn   = root.querySelector('.psnl-btn');
		var chk   = root.querySelector('.psnl-check');
		var hp    = root.querySelector('.psnl-website');
		var msg   = root.querySelector('.psnl-msg');
		if (!email || !btn || !chk || !msg) { return; }

		function rodyk(tekstas, tipas) {
			msg.textContent = tekstas;
			msg.className = 'psnl-msg ' + (tipas === 'ok' ? 'ok' : 'er');
		}

		function siusk() {
			msg.className = 'psnl-msg';
			var adresas = (email.value || '').trim();
			if (!adresas) { rodyk('Įveskite el. pašto adresą.', 'er'); email.focus(); return; }
			if (!chk.checked) { rodyk('Pažymėkite, kad sutinkate gauti naujienas.', 'er'); chk.focus(); return; }

			btn.disabled = true;
			var senas = btn.textContent;
			btn.textContent = 'Siunčiama...';

			fetch(PS_NL.rest, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json', 'X-WP-Nonce': PS_NL.nonce },
				credentials: 'same-origin',
				body: JSON.stringify({
					email: adresas,
					consent: chk.checked ? 1 : 0,
					website: hp ? hp.value : '',
					source: root.getAttribute('data-source') || 'newsletter_form'
				})
			})
			.then(function (r) { return r.json().then(function (d) { return { st: r.status, d: d }; }); })
			.then(function (x) {
				if (x.d && x.d.ok) {
					rodyk(x.d.message || 'Ačiū!', 'ok');
					email.value = '';
					chk.checked = false;
					btn.textContent = senas;
					btn.disabled = true;          // pakartotinai nespaudžiam
				} else {
					rodyk((x.d && x.d.message) || 'Nepavyko. Pabandykite vėliau.', 'er');
					btn.textContent = senas;
					btn.disabled = false;
				}
			})
			.catch(function () {
				rodyk('Nepavyko susisiekti. Patikrinkite ryšį.', 'er');
				btn.textContent = senas;
				btn.disabled = false;
			});
		}

		btn.addEventListener('click', siusk);
		email.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); siusk(); } });
	}

	function start() {
		var v = document.querySelectorAll('.psnl');
		for (var i = 0; i < v.length; i++) { init(v[i]); }
	}
	if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', start); }
	else { start(); }
})();
